#include "files.hpp"
#include <algorithm>
#include <atomic>
#include <chrono>
#include <fstream>
#include <iostream>
#include <iterator>
#include <stdexcept>

#ifdef _WIN32
#include <fcntl.h>
#include <io.h>
#endif

std::string blitz::tools::read_file(std::filesystem::path const& file)
{
	std::ifstream stream(file, std::ios_base::binary);
	if (!stream.good()) {
		throw std::runtime_error("Reading '" + file.generic_string() + "' failed.");
	}
	return std::string(std::istreambuf_iterator<char>(stream), std::istreambuf_iterator<char>());
}

std::string blitz::tools::read_stdin()
{
#ifdef _WIN32
	_setmode(_fileno(stdin), _O_BINARY);
#endif
	return std::string(std::istreambuf_iterator<char>(std::cin), std::istreambuf_iterator<char>());
}

void blitz::tools::write_file(std::filesystem::path const& file, std::string const& data)
{
	// The new contents are written to a file of their own that then takes the place of the old one, so that a file that can't be written
	// completely (a full disk, a program that is stopped) is the old one and not half of the new one. A link is followed to its file first,
	// as it is the file and not the link that is meant, and the file keeps the permissions that it had.
	std::error_code       ec;
	std::filesystem::path target = file;
	if (std::filesystem::is_symlink(file, ec)) {
		target = std::filesystem::canonical(file, ec);
		if (ec) {
			throw std::runtime_error("Writing '" + file.generic_string() + "' failed: " + ec.message());
		}
	}
	ec.clear(); // A file that is not there yet is fine.
	static std::atomic<unsigned> counter{ 0 };
	std::filesystem::path        temporary = target.parent_path() / ("." + target.filename().generic_string() + "." + std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()) + "-" + std::to_string(counter++) + ".tmp");
	{
		std::ofstream stream(temporary, std::ios_base::binary | std::ios_base::trunc);
		if (!stream.is_open()) {
			// A file that can be written to in a folder that can't: the file itself is all there is to write to.
			std::ofstream direct(target, std::ios_base::binary | std::ios_base::trunc);
			direct.write(data.data(), (std::streamsize)data.size());
			direct.flush();
			if (!direct.good()) {
				throw std::runtime_error("Writing '" + file.generic_string() + "' failed.");
			}
			return;
		}
		stream.write(data.data(), (std::streamsize)data.size());
		stream.flush();
		if (!stream.good()) {
			stream.close();
			std::filesystem::remove(temporary, ec);
			throw std::runtime_error("Writing '" + file.generic_string() + "' failed.");
		}
	}
	auto status = std::filesystem::status(target, ec);
	if (!ec && std::filesystem::exists(status)) {
		std::filesystem::permissions(temporary, status.permissions(), ec);
	}
	std::filesystem::rename(temporary, target, ec);
	if (ec) {
		std::error_code ignored;
		std::filesystem::remove(temporary, ignored);
		throw std::runtime_error("Writing '" + file.generic_string() + "' failed: " + ec.message());
	}
}

std::vector<std::filesystem::path> blitz::tools::find_sources(std::filesystem::path const& directory)
{
	std::vector<std::filesystem::path> found;
	std::error_code                    ec;
	std::filesystem::recursive_directory_iterator it(directory, ec), end;
	if (ec) {
		throw std::runtime_error("Reading the directory '" + directory.generic_string() + "' failed: " + ec.message());
	}
	for (; it != end; it.increment(ec)) {
		if (ec) {
			throw std::runtime_error("Reading the directory '" + directory.generic_string() + "' failed: " + ec.message());
		}
		// A link is not followed to a file, which can be anywhere and would be rewritten with -i.
		if (it->is_symlink(ec) || !it->is_regular_file(ec)) {
			continue;
		}
		std::string extension = it->path().extension().string();
		for (auto& c : extension) {
			c = (c >= 'A' && c <= 'Z') ? char(c - 'A' + 'a') : c;
		}
		// Only .bb: .b3d is a model format as well, and .bp is not source code either.
		if (extension == ".bb") {
			found.push_back(it->path());
		}
	}
	std::sort(found.begin(), found.end());
	return found;
}
